/* eslint-disable import/first */
// with `action` (and, for user-targeted actions, `targetId`), the password typed in the form or
// the code generated by `generateOtpCode` is checked server-side at POST /users/confirm_action, not against
// the legacy check_password. `confirmActionStatus.result.confirmation_token` is what the protected request
// (POST /users/{id}, the bulk DELETEs) then carries; `confirmActionStatus.error` is the API's error list.
// Without `action` nothing here runs: `getCheckPassword` keeps hitting check_password, as before (OrdersManage
// and the other controllers that hand ConfirmAdmin no `action` yet, 's deferred UserAddForm included).
import React from 'react'
import { act, render, waitFor } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

vi.mock('../../../contexts/ApiContext', () => ({
  useApi: () => [{ root: 'https://api.test', appId: 'app-x', appInternalName: 'app-internal' }]
}))
vi.mock('../../../contexts/SessionContext', () => ({
  useSession: () => [{ token: 'session-token', user: { id: 1, level: 0 } }]
}))

import { CheckPassword } from '../index'

const RealFetch = global.fetch
let ui

const mount = async (props = {}) => {
  ui = null
  render(<CheckPassword UIComponent={(p) => { ui = p; return null }} {...props} />)
  await waitFor(() => expect(ui).not.toBeNull())
}

afterEach(() => { global.fetch = RealFetch })
beforeEach(() => { ui = null })

describe('CheckPassword · confirmAction', () => {
  it('with a password and no code, posts { action, target_id, password } to /users/confirm_action', async () => {
    global.fetch = vi.fn(async () => ({ json: async () => ({ error: false, result: { confirmation_token: 'tok-1', expires_in: 120 } }) }))
    await mount({ action: 'users_delete' })
    act(() => ui.handleChangeCredentials({ password: 'secret-1' }))
    await act(async () => { await ui.getCheckPassword() })

    expect(global.fetch).toHaveBeenCalledTimes(1)
    const [url, options] = global.fetch.mock.calls[0]
    expect(url).toBe('https://api.test/users/confirm_action')
    expect(options.method).toBe('POST')
    expect(options.headers.Authorization).toBe('Bearer session-token')
    expect(JSON.parse(options.body)).toEqual({ action: 'users_delete', password: 'secret-1' })
  })

  it('target_id travels for a user-targeted action', async () => {
    global.fetch = vi.fn(async () => ({ json: async () => ({ error: false, result: { confirmation_token: 'tok-1', expires_in: 120 } }) }))
    await mount({ action: 'user_enabled', targetId: 42 })
    act(() => ui.handleChangeCredentials({ password: 'secret-1' }))
    await act(async () => { await ui.getCheckPassword() })

    expect(JSON.parse(global.fetch.mock.calls[0][1].body)).toEqual({ action: 'user_enabled', target_id: 42, password: 'secret-1' })
  })

  it('a code (not the password) is sent when confirmAction is called with one', async () => {
    global.fetch = vi.fn(async () => ({ json: async () => ({ error: false, result: { confirmation_token: 'tok-otp', expires_in: 120 } }) }))
    await mount({ action: 'orders_delete' })
    await act(async () => { await ui.confirmAction('482915') })

    expect(JSON.parse(global.fetch.mock.calls[0][1].body)).toEqual({ action: 'orders_delete', code: '482915' })
  })

  it('on success, confirmActionStatus.result carries the confirmation_token (what the caller must send next)', async () => {
    global.fetch = vi.fn(async () => ({ json: async () => ({ error: false, result: { confirmation_token: 'tok-9', expires_in: 120 } }) }))
    await mount({ action: 'orders_delete' })
    await act(async () => { await ui.confirmAction('482915') })

    expect(ui.confirmActionStatus).toEqual({ result: { confirmation_token: 'tok-9', expires_in: 120 }, loading: false, error: null })
  })

  it('on a wrong code or password, confirmActionStatus.error carries the API message and there is no token', async () => {
    global.fetch = vi.fn(async () => ({ json: async () => ({ error: true, result: ['Incorrect code'] }) }))
    await mount({ action: 'orders_delete' })
    await act(async () => { await ui.confirmAction('000000') })

    expect(ui.confirmActionStatus).toEqual({ result: null, loading: false, error: ['Incorrect code'] })
  })

  // (coordinator update): after 5 failed attempts in 10 min the API answers
  // `error_codes: ['admin_confirmation.too_many_attempts']` with the message in `result`; it is shown the
  // same way as any other confirm_action error, with no special handling needed.
  it('a too-many-attempts answer surfaces its message through confirmActionStatus.error like any other error', async () => {
    global.fetch = vi.fn(async () => ({
      json: async () => ({ error: true, error_codes: ['admin_confirmation.too_many_attempts'], result: ['Too many attempts. Try again later.'] })
    }))
    await mount({ action: 'orders_delete' })
    await act(async () => { await ui.confirmAction('000000') })

    expect(ui.confirmActionStatus).toEqual({ result: null, loading: false, error: ['Too many attempts. Try again later.'] })
  })

  it('without an action, getCheckPassword keeps calling the legacy /users/check_password, untouched', async () => {
    global.fetch = vi.fn(async () => ({ json: async () => ({ error: false, result: 'OK' }) }))
    await mount({})
    act(() => ui.handleChangeCredentials({ password: 'secret-1' }))
    await act(async () => { await ui.getCheckPassword() })

    expect(global.fetch).toHaveBeenCalledWith('https://api.test/users/check_password', expect.objectContaining({ method: 'POST' }))
    expect(JSON.parse(global.fetch.mock.calls[0][1].body)).toEqual({ password: 'secret-1' })
  })
})
